<?php
declare(strict_types=1);
require_once __DIR__ . '/access.php';
require_once __DIR__ . '/activity.php';
require_once __DIR__ . '/notifications.php';
require_login();
$contentId = (int) ($_GET['content_id'] ?? $_POST['content_id'] ?? 0); $user = $_SESSION['user']; $pdo = db(); if ($contentId === 0 && $user['role'] === 'admin') { header('Location: admin_content_queue.php'); exit; }
$stmt = $pdo->prepare("SELECT c.*, cl.name AS client_name FROM content c INNER JOIN clients cl ON cl.id = c.client_id WHERE c.id = ? AND (cl.user_id = ? OR c.employee_id = ? OR EXISTS (SELECT 1 FROM client_employees ce WHERE ce.client_id = c.client_id AND ce.employee_id = ?) OR ? = 'admin')");
$stmt->execute([$contentId, $user['id'], $user['id'], $user['id'], $user['role']]); $content = $stmt->fetch();
if (!$content) { http_response_code(404); exit('Content not found or access denied.'); }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    header('Content-Type: application/json; charset=utf-8');
    try {
        verify_csrf(); $action = (string) ($_POST['action'] ?? ''); $message = trim((string) ($_POST['message'] ?? ''));
        if ($action === 'admin_status_override') {
            if ($user['role'] !== 'admin') { throw new RuntimeException('Only an admin can override content status.'); }
            $status = (string)($_POST['status'] ?? '');
            if (!in_array($status, ['pending', 'approved', 'changes_requested'], true) || $message === '') { throw new RuntimeException('Choose a valid status and enter a reason.'); }
            $pdo->beginTransaction();
            $pdo->prepare('UPDATE content SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?')->execute([$status, $contentId]);
            $pdo->prepare('INSERT INTO content_status_history (content_id, user_id, old_status, new_status, note) VALUES (?, ?, ?, ?, ?)')->execute([$contentId, $user['id'], $content['status'], $status, 'Admin override: ' . $message]);
            $pdo->commit();
            log_activity((int)$user['id'], 'Admin content status override', 'content', $contentId);
            if ($user['role'] === 'admin' && empty($_SERVER['HTTP_X_REQUESTED_WITH'])) { header('Location: admin_content_view.php?content_id=' . $contentId . '&saved=1'); exit; }
            echo json_encode(['ok' => true, 'message' => 'Admin status override saved.']); exit;
        }
        if ($action === 'approve' || $action === 'request_changes') {
            if ($user['role'] !== 'client') { throw new RuntimeException('Only the client can change approval status.'); }
            if ($action === 'request_changes' && $message === '') { throw new RuntimeException('A comment is required when requesting changes.'); }
            $status = $action === 'approve' ? 'approved' : 'changes_requested'; $pdo->beginTransaction();
            if ($message !== '') { $pdo->prepare('INSERT INTO comments (content_id, user_id, message) VALUES (?, ?, ?)')->execute([$contentId, $user['id'], $message]); }
            $pdo->prepare('UPDATE content SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?')->execute([$status, $contentId]);
            $pdo->prepare('INSERT INTO content_status_history (content_id, user_id, old_status, new_status, note) VALUES (?, ?, ?, ?, ?)')->execute([$contentId, $user['id'], $content['status'], $status, $message ?: null]); $pdo->commit();
            log_activity((int) $user['id'], $status === 'approved' ? 'Approved content' : 'Requested content changes', 'content', $contentId);
            $notify = $pdo->prepare('SELECT email FROM users WHERE id = ?'); $notify->execute([$content['employee_id']]); if ($employeeEmail = $notify->fetchColumn()) { send_notification((string) $employeeEmail, 'Content status updated', 'The content "' . $content['title'] . '" is now ' . str_replace('_', ' ', $status) . '.'); }
            echo json_encode(['ok' => true, 'message' => 'Content status updated.']); exit;
        }
        if ($action === 'comment') { if ($message === '') { throw new RuntimeException('Comment cannot be empty.'); } $pdo->prepare('INSERT INTO comments (content_id, user_id, message) VALUES (?, ?, ?)')->execute([$contentId, $user['id'], $message]); echo json_encode(['ok' => true, 'message' => 'Comment added.']); exit; }
        throw new RuntimeException('Unknown action.');
    } catch (Throwable $exception) { if ($pdo->inTransaction()) { $pdo->rollBack(); } http_response_code(422); echo json_encode(['ok' => false, 'message' => $exception->getMessage()]); exit; }
}
$stmt = $pdo->prepare('SELECT id, file_path, version FROM content_files WHERE content_id = ? ORDER BY version DESC, sort_order, id'); $stmt->execute([$contentId]); $files = $stmt->fetchAll();
$stmt = $pdo->prepare('SELECT comments.message, comments.created_at, users.name, users.role FROM comments INNER JOIN users ON users.id = comments.user_id WHERE comments.content_id = ? ORDER BY comments.created_at'); $stmt->execute([$contentId]); $comments = $stmt->fetchAll();
$stmt = $pdo->prepare('SELECT h.new_status, h.note, h.created_at, u.name FROM content_status_history h INNER JOIN users u ON u.id = h.user_id WHERE h.content_id = ? ORDER BY h.created_at DESC'); $stmt->execute([$contentId]); $history = $stmt->fetchAll();
$isClient = $user['role'] === 'client';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Review Content</title><link rel="stylesheet" href="assets/css/saas.css"><style>.review-card{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:22px;box-shadow:0 4px 20px rgba(15,23,42,.05)}.review-files{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.review-files img,.review-files video{width:100%;border-radius:12px;display:block}.comment{border-bottom:1px solid #e2e8f0;padding:12px 0}.comment:last-child{border-bottom:0}.profile-input{width:100%;border:1px solid #dbe2ea;border-radius:10px;padding:10px;font:inherit}@media(max-width:700px){.review-files{grid-template-columns:1fr}}</style><script src="assets/js/session-timeout.js" defer></script></head><body class="<?= $isClient ? 'saas-body' : 'bg-light' ?>"><?php if ($isClient): ?><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><div class="nav-label">Workspace</div><a class="saas-nav" href="client_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav" href="client_content_plan.php">◷ <span>Content plan</span></a><a class="saas-nav" href="content_archive.php">▤ <span>Archive</span></a><a class="saas-nav" href="view_client_profile.php?client_id=<?= $content['client_id'] ?>">♙ <span>My profile</span></a><a class="saas-nav" href="my_invoices.php">▧ <span>Invoices</span></a><div class="nav-label">Account</div><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><?php else: ?><main class="container py-4"><?php endif; ?><header class="saas-topbar"><div><h1 class="saas-title"><?= e($content['title']) ?></h1><div class="saas-subtitle"><?= e($content['client_name']) ?> · <?= e(ucfirst($content['content_type'])) ?></div></div><a href="<?= $isClient ? 'client_dashboard.php' : ($user['role'] === 'admin' ? 'admin_dashboard.php' : 'employee_dashboard.php') ?>">Dashboard</a></header><div id="notice"></div><section class="review-card" style="margin-bottom:16px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px"><span class="status-pill status-<?= e($content['status']) ?>"><?= e(ucwords(str_replace('_', ' ', $content['status']))) ?></span><small class="saas-subtitle">Content ID #<?= $contentId ?></small></div><?php if ($content['caption']): ?><p><?= nl2br(e($content['caption'])) ?></p><?php endif; ?><div class="review-files"><?php foreach ($files as $file): ?><div><small class="saas-subtitle" style="display:block;margin-bottom:5px">Version <?= (int) $file['version'] ?></small><?php if ($content['content_type'] === 'video' && !filter_var($file['file_path'], FILTER_VALIDATE_URL)): ?><video controls src="<?= e($file['file_path']) ?>"></video><?php elseif ($content['content_type'] !== 'video' && !filter_var($file['file_path'], FILTER_VALIDATE_URL)): ?><img src="<?= e($file['file_path']) ?>" alt="Content preview"><?php else: ?><a class="btn-outline-indigo" href="<?= e($file['file_path']) ?>" target="_blank" rel="noopener">Open external content link</a><?php endif; ?></div><?php endforeach; ?></div></section><?php if ($user['role'] === 'employee' && $content['status'] === 'changes_requested'): ?><section class="review-card" style="margin-bottom:16px"><h2>Changes requested</h2><a class="btn-indigo" href="upload_content.php?resubmit_content_id=<?= $contentId ?>">Re-upload new version</a></section><?php endif; ?><?php if ($isClient): ?><section class="review-card" style="margin-bottom:16px"><h2>Your decision</h2><form class="ajax-form" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="content_id" value="<?= $contentId ?>"><input type="hidden" name="action" value="approve"><textarea class="profile-input" name="message" rows="2" placeholder="Optional comment"></textarea><br><button class="btn-indigo" style="margin-top:8px">Approve content</button></form><form class="ajax-form" method="post" style="margin-top:14px"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="content_id" value="<?= $contentId ?>"><input type="hidden" name="action" value="request_changes"><textarea class="profile-input" name="message" rows="2" placeholder="Explain the changes needed" required></textarea><br><button class="btn-outline-indigo" style="margin-top:8px">Request changes</button></form></section><?php endif; ?><section class="review-card" style="margin-bottom:16px"><h2>Revision history</h2><?php foreach ($history as $item): ?><div class="comment"><strong><?= e(ucwords(str_replace('_', ' ', $item['new_status']))) ?></strong> by <?= e($item['name']) ?><br><small class="saas-subtitle"><?= e($item['created_at']) ?></small><?php if ($item['note']): ?><div><?= nl2br(e($item['note'])) ?></div><?php endif; ?></div><?php endforeach; ?></section><section class="review-card"><h2>Comments</h2><?php foreach ($comments as $comment): ?><div class="comment"><strong><?= e($comment['name']) ?></strong> <span class="status-pill"><?= e($comment['role']) ?></span><br><small class="saas-subtitle"><?= e($comment['created_at']) ?></small><div style="margin-top:4px"><?= nl2br(e($comment['message'])) ?></div></div><?php endforeach; ?><?php if (!$comments): ?><p class="saas-subtitle">No comments yet.</p><?php endif; ?><form class="ajax-form" method="post" style="margin-top:14px"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="content_id" value="<?= $contentId ?>"><input type="hidden" name="action" value="comment"><textarea class="profile-input" name="message" rows="2" placeholder="Add a comment" required></textarea><br><button class="btn-outline-indigo" style="margin-top:8px">Add comment</button></form></section></main><?php if ($isClient): ?></div><?php endif; ?><script>document.querySelectorAll('.ajax-form').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const response=await fetch('approve_content.php',{method:'POST',body:new FormData(form)}),data=await response.json();document.getElementById('notice').innerHTML='<div class="alert '+(data.ok?'alert-success':'alert-danger')+'">'+data.message+'</div>';if(data.ok)setTimeout(()=>location.reload(),700)}));</script></body></html>
